async function stop(service){if(service.child.exitCode!==null)return;service.child.send?.({type:'riftcast-shutdown'});await Promise.race([new Promise(r=>service.child.once('exit',r)),delay(3000)]);if(service.child.exitCode===null)service.child.kill('SIGTERM');}
async function get(service){return fetch(service.base+'/api/state').then(r=>r.json());}
async function api(service,route,body,token){const response=await fetch(service.base+route,{...(body?{method:'POST',headers:{'content-type':'application/json',...(token?{'x-seat-token':token}:{})},body:JSON.stringify(body)}:{})});let data;try{data=await response.json();}catch{data=null;}return{status:response.status,data};}
async function action(service,body,token=service===mock?mockToken:ownerToken,version){const s=await get(service);const result=await api(service,'/api/action',{...body,expectedConfigVersion:version??s.production.configVersion,requestId:body.requestId||crypto.randomUUID()},token);assert.equal(result.status,200,JSON.stringify(result.data));return result.data;}
async function setFixture(patch){fixture={...fixture,...patch};await new Promise((resolve,reject)=>{const id=crypto.randomUUID(),timer=setTimeout(()=>reject(Error('Fixture IPC timeout')),3000);const listener=m=>{if(m?.type==='sol-fixture-ack'&&m.id===id){clearTimeout(timer);mock.child.off('message',listener);resolve();}};mock.child.on('message',listener);mock.child.send({type:'sol-fixture',id,connected:fixture.connected??true,applyFailure:fixture.applyFailure??false});});}
async function context(service,options={},token){const c=await browser.newContext({viewport:{width:1366,height:736},locale:'zh-CN',...options});if(token)await c.addInitScript(value=>{if(location.protocol==='http:'||location.protocol==='https:')sessionStorage.setItem('riftcast-seat-token',value);},token);
 await c.route('**/*',async route=>{const request=route.request(),url=new URL(request.url());if(url.origin!==service.base)return route.abort();if(url.pathname==='/api/resources/asset')return route.fulfill({json:{data:{}}});if(service.hook&&url.pathname.startsWith('/api/obs/'))return fixtureRpc(route,url.pathname);if(request.method()!=='GET'&&(url.pathname.startsWith('/api/obs/')||url.pathname==='/api/connect'))return route.fulfill({status:403,json:{error:'Sol forbids real engine/device actions'}});return route.continue();});
 c.on('page',p=>{p.__solMock=service.hook;p.setDefaultTimeout(5000);p.on('pageerror',e=>errors.push({scope:service.name,error:e.message}));p.on('request',r=>{if(r.method()==='POST'&&r.url().endsWith('/api/action')){try{const a=r.postDataJSON();requests.push({scope:service.name,type:a.type,operation:a.command?.op,requestId:!!a.requestId,configVersion:a.expectedConfigVersion});}catch{}}});});return c;}
function engineStatus(){return structuredClone(fixture.engine);}
async function fixtureRpc(route,pathname){const req=route.request(),body=req.method()==='GET'?null:req.postDataJSON?.();
 if(req.method()==='GET'){
  if(pathname==='/api/obs/engine'){if(fixture.statusError)return route.fulfill({status:503,json:{error:'Sol synthetic status unavailable'}});return route.fulfill({json:engineStatus()});}
  if(pathname==='/api/obs/production')return route.fulfill({json:{audio:fixture.audio,disk:{detail:'未测量'},recording:null,bufferActive:false,emergencyAvailable:true,gameSource:'Sol synthetic',audioManaged:fixture.engine.companionAudio.managing,companionAudio:fixture.engine.companionAudio,music:fixture.music}});
  if(pathname==='/api/obs/custom-sources')return route.fulfill({json:{windows:[{name:'Sol 合成窗口（非真实设备）',value:'sol-window'}],inputs:[{name:'Sol 共享来源（非真实 OBS）',kind:'image_source'}]}});
  return route.fulfill({status:400,json:{error:'Sol fixture supplies no real preview or device'}});
 }
 requests.push({scope:'mock',endpoint:pathname,action:body?.action,destination:body?.destination,keyPresent:!!body?.key});
 if(pathname==='/api/obs/engine/output'){
  const a=body.action;if(a==='start-virtual-camera'){fixture.engine.virtualCamActive=true;fixture.engine.companionAudio.active=!fixture.partialStart;fixture.engine.companionAudio.managing=true;if(fixture.partialStart)fixture.engine.companionAudio.error='Sol 合成音频启动失败';}
  if(a==='stop-virtual-camera'){fixture.engine.virtualCamActive=false;fixture.engine.companionAudio.active=false;fixture.engine.companionAudio.managing=!!fixture.restoreFailure;fixture.engine.companionAudio.error=fixture.restoreFailure?'Sol 合成路由恢复失败':undefined;}
  if(a==='start-record'||a==='stop-record')fixture.engine.recordActive=a==='start-record';if(a==='start-stream'||a==='stop-stream')fixture.engine.streamActive=a==='start-stream';return route.fulfill({json:engineStatus()});
 }
 if(pathname==='/api/obs/engine/destination'){fixture.engine.destination=body.destination;return route.fulfill({json:engineStatus()});}
 if(pathname==='/api/obs/stream/settings')return route.fulfill({json:{applied:true}});
 if(pathname==='/api/obs/music/control'){fixture.music.state=body.action==='play'?'OBS_MEDIA_STATE_PLAYING':body.action==='pause'?'OBS_MEDIA_STATE_PAUSED':'OBS_MEDIA_STATE_STOPPED';fixture.music.playing=body.action==='play';return route.fulfill({json:fixture.music});}
 if(pathname==='/api/obs/production'){const bus=fixture.audio.find(x=>x.name===body?.name);if(bus)Object.assign(bus,Object.fromEntries(Object.entries(body).filter(([k])=>['db','muted','syncOffset','monitor'].includes(k))));return route.fulfill({json:{audio:fixture.audio,disk:{detail:'未测量'},recording:null,bufferActive:false,emergencyAvailable:true,gameSource:'Sol synthetic',audioManaged:fixture.engine.companionAudio.managing,companionAudio:fixture.engine.companionAudio,music:fixture.music}});}
 return route.fulfill({status:403,json:{error:'Sol blocks setup/install/real engine actions'}});
}
