 await check('overlay-teamfight-theme','Teamfight remains transparent and does not gain console text across themes',async()=>{await overlay.evaluate(()=>document.getElementById('sol-fixture-badge')?.remove());await action(mock,{type:'take',scene:'teamfight'});await overlay.waitForFunction(()=>document.querySelector('.broadcast-canvas')?.className?.includes('teamfight'));const fingerprint=()=>overlay.locator('.broadcast-canvas').evaluate(e=>[e,...e.querySelectorAll('*')].map(n=>[n.tagName,n.textContent,getComputedStyle(n).backgroundColor,getComputedStyle(n,'::before').backgroundColor,getComputedStyle(n,'::after').backgroundColor]));const before=await fingerprint();await mp.evaluate(()=>localStorage.setItem('riftcast-ui-theme','light'));await mp.reload();await delay(120);assert.deepEqual(await fingerprint(),before);assert.equal(await overlay.locator('.broadcast-canvas').innerText(),'');await snap(overlay,'overlay-teamfight-transparent');});
